package dev.industrialtechnology.expansion;
import net.minecraft.inventory.*;import net.minecraft.entity.player.*;import net.minecraft.item.*;import net.minecraft.nbt.*;import dev.industrialtechnology.railway.*;import dev.industrialtechnology.core.IndustrialTechnology;
public final class ExpansionContainer extends Container {
 public final EntityRollingStock train;public final TileRailStation station;private NBTTagCompound previous;private int ticks,actions;private long actionAt=Long.MIN_VALUE;public final int playerStart;
 public ExpansionContainer(EntityPlayer p,EntityRollingStock t,TileRailStation r){train=t;station=r;if(r!=null&&r.kind()!=0)for(int i=0;i<9;i++)addSlotToContainer(new Slot(r,i,8+i*18,87));playerStart=inventorySlots.size();if(t!=null||r!=null){for(int row=0;row<3;row++)for(int col=0;col<9;col++)addSlotToContainer(new Slot(p.inventory,9+row*9+col,8+18*col,119+18*row));for(int col=0;col<9;col++)addSlotToContainer(new Slot(p.inventory,col,8+18*col,177));}}
 @Override public boolean canInteractWith(EntityPlayer p){if(train!=null)return !train.isDead&&p.worldObj==train.worldObj&&train.permitted(p)&&(p.ridingEntity==train||p.getDistanceSqToEntity(train)<256);if(station!=null)return station.usable(p);return false;}
 public NBTTagCompound snapshot(){return train!=null?train.snapshot():station!=null?station.snapshot():new NBTTagCompound();}public void send(EntityPlayerMP p){IndustrialTechnology.network.sendTo(new ExpansionSnapshot(windowId,snapshot()),p);}
 @Override public void addCraftingToCrafters(ICrafting c){super.addCraftingToCrafters(c);if(c instanceof EntityPlayerMP)send((EntityPlayerMP)c);}@Override public void detectAndSendChanges(){super.detectAndSendChanges();if(++ticks<10)return;ticks=0;NBTTagCompound n=snapshot();if(n.equals(previous))return;previous=n;for(Object c:crafters)if(c instanceof EntityPlayerMP)send((EntityPlayerMP)c);}
 public boolean actionAllowed(EntityPlayer p){long now=p.worldObj.getTotalWorldTime();if(actionAt!=now){actionAt=now;actions=0;}return ++actions<=8;}
 public void logicalClick(EntityPlayer p,int slot,boolean one,boolean toInventory){if(train==null||!train.permitted(p))return;LogicalCargo cargo=train.stock==StockType.STEAM?train.fuel:train.stock==StockType.FREIGHT?train.cargo:null;if(cargo==null||slot<0||slot>=cargo.slots())return;ItemStack cursor=p.inventory.getItemStack();if(cursor!=null&&!toInventory){int n=cargo.insert(slot,cursor,one?1:cursor.stackSize,false);cursor.stackSize-=n;if(cursor.stackSize<=0)p.inventory.setItemStack(null);}else{ItemStack out=cargo.extract(slot,one?1:64,true);if(out==null)return;if(toInventory){int before=out.stackSize;p.inventory.addItemStackToInventory(out);int inserted=before-out.stackSize;cargo.extract(slot,inserted,false);}else if(cursor==null){p.inventory.setItemStack(cargo.extract(slot,one?1:64,false));}}p.inventory.markDirty();if(p instanceof EntityPlayerMP){((EntityPlayerMP)p).updateHeldItem();send((EntityPlayerMP)p);}}
 @Override public ItemStack transferStackInSlot(EntityPlayer p,int index){if(index<0||index>=inventorySlots.size())return null;Slot slot=(Slot)inventorySlots.get(index);ItemStack stack=slot.getStack();if(stack==null)return null;ItemStack old=stack.copy();if(train!=null){LogicalCargo cargo=train.stock==StockType.STEAM?train.fuel:train.stock==StockType.FREIGHT?train.cargo:null;if(cargo==null)return null;for(int i=0;i<cargo.slots();i++){int n=cargo.insert(i,stack,stack.stackSize,false);stack.stackSize-=n;if(stack.stackSize==0)break;}}else if(station!=null&&station.kind()!=0){if(index<playerStart){if(!mergeItemStack(stack,playerStart,inventorySlots.size(),true))return null;}else if(!mergeItemStack(stack,0,playerStart,false))return null;}else return null;if(stack.stackSize<=0)slot.putStack(null);else slot.onSlotChanged();return old;}
}
